/* ===========================================================================
   SUN STATE INTERNATIONAL — site-wide type and component corrections
   ---------------------------------------------------------------------------
   Ported from the design handoff's base.css + components.css onto the
   renderer's own classes. The design system (site/tokens.json) supplies every
   colour, size and space used below; nothing here invents a value.

   Why this file exists: the renderer's defaults set UI text in the heading
   face, and INTL Headline is a CAPS-ONLY face — so nav links, footer links and
   inline links rendered as uppercase where the design sets them in the body
   face (INTL Text). The eyebrow default is also accent red where the design's
   is muted grey. Both are global type decisions, which is why they live here
   rather than being repeated per section.
   =========================================================================== */

/* ------------------------------------------------------------- document */

body { background: var(--card); color: #242424; font-size: 15px; overflow-x: hidden; text-wrap: pretty; }

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

/* --------------------------------------------------------------- type ---
   The handoff's scale, applied to the block wrappers the renderer emits. */

.bz-block h1 { font: 800 var(--text-h1) / 1.05 var(--font-heading); letter-spacing: -0.01em; margin: 0 0 26px; }
/* The handoff tracks only the hero display line; section titles sit at normal,
   and the renderer's own default of -0.01em changes where they wrap. */
.bz-block h2 { font: 800 var(--text-h2) / 1.15 var(--font-heading); letter-spacing: normal; margin: 0 0 var(--space-7); }
.bz-block h3 { font: 700 var(--text-h3) / 1.2 var(--font-heading); margin: 0 0 var(--space-4); }
.bz-block h4 { font: 700 24px / 1.3 var(--font-heading); margin: 0 0 var(--space-2); }

.bz-block p { font-size: var(--text-body); line-height: 1.6; color: #3f3f3f; margin: 0 0 var(--space-4); }
.bz-block p:last-child { margin-bottom: 0; }

/* Eyebrow: muted grey in the body face, tracked out. Not accent red.
   Matched as `.bz-block p.bz-eyebrow` because the renderer sets body copy with
   `.bz-block p`, which would otherwise win on specificity. */
.bz-block p.bz-eyebrow, .bz-eyebrow {
  font: 700 var(--text-eyebrow) / 1 var(--font-body);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 18px;
}
.bz-section--bg-ink .bz-eyebrow { color: #E2E2E2; }
.bz-section--bg-accent .bz-eyebrow { color: #FFD9D5; }

.bz-lede { font-size: var(--text-body); line-height: 1.7; color: #3f3f3f; max-width: 680px; }

/* Copy on a dark band */
.bz-section--bg-ink .bz-block p { color: #C7C1B4; }
.bz-section--bg-ink h1, .bz-section--bg-ink h2, .bz-section--bg-ink h3, .bz-section--bg-ink h4 { color: #fff; }

/* ------------------------------------------------------------ buttons ---
   The handoff's one button primitive: 46px tall, 16px sides, hard-edged. */

.bz-btns { gap: var(--space-3); margin-block: 0; }
.bz-btn {
  gap: 8px;
  min-height: 46px;
  padding: 0 16px;
  font: 700 var(--text-small) / 1 var(--font-heading);
  border: none;
  border-radius: var(--radius-input);
}
.bz-btn--primary { background: var(--accent); color: #fff; }
.bz-btn--primary:hover { background: var(--accent-dark); color: #fff; }
.bz-btn--secondary {
  background: var(--card);
  color: var(--ink);
  border: 1px solid var(--line);
  font: 600 var(--text-small) / 1 var(--font-body);
}

/* The handoff's `.btn--ghost` / `.arrow-link`: a bold accent text link in the
   body face, so it reads in sentence case rather than the caps display face. */
.bz-btn--link {
  min-height: 20px;
  padding: 0;
  background: none;
  font: 600 var(--text-small) / 1.6 var(--font-body);
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}
.bz-btn--link:hover { color: var(--accent-dark); }

/* ---------------------------------------------------------------- nav ---
   Menus are UI, not display type: body face, sentence case. */

.bz-navitem > a,
.bz-navitem > button,
.bz-navitem > .bz-navlabel {
  font: 600 var(--text-small) / 1 var(--font-body);
}
.bz-nav { gap: var(--space-2); }

/* Mega panel: white full-width sheet, muted tracked column headings. */
.bz-menu--mega .bz-subnav > .bz-navitem > .bz-navlabel {
  font: 700 var(--text-eyebrow) / 1 var(--font-body);
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-bottom: 18px;
}
.bz-menu--mega .bz-navitem--has-sub > .bz-subnav a { color: var(--ink); }
.bz-menu--mega .bz-navitem--has-sub > .bz-subnav a:hover { color: var(--accent); text-decoration: none; }

/* ---------------------------------------------------------- container ---
   The design's container is 1280px with a 48px gutter, which is exactly what
   tokens.layout says. The renderer's own section rule hardcodes the small
   step instead of reading that token, so copy would sit 32px too far out on
   every boxed section. Point it back at the token. */

.bz-section > .bz-container { padding-inline: var(--container-pad); }
@media (max-width: 1100px) { .bz-section > .bz-container { padding-inline: var(--container-pad-tablet); } }
@media (max-width: 640px) { .bz-section > .bz-container { padding-inline: var(--container-pad-mobile); } }

/* --------------------------------------------------------------- misc ---
   Figures carry no radius in a hard-edged theme. */

.bz-figure img { border-radius: 0; }
